import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png";

export default function Index() {
  return (
    <>
      {/* garde la navbar fixe si tu veux qu’elle reste visible */}
      <IndexNavbar fixed />

      {/* HERO avec image en background — démarre sous le nav */}

      <section
        className="relative flex items-center h-screen max-h-860-px mt-16 md:mt-20"
        style={{
          backgroundImage: `url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
        }}
      >
        {/* Overlay marron */}
        <div className="absolute inset-0" style={{ backgroundColor: "rgba(101, 67, 33, 0.55)" }}></div>
        {/* rgba(101,67,33,0.55) = marron avec opacité 55% */}

        <div className="container mx-auto flex flex-wrap items-center relative z-10">
          <div className="w-full lg:w-6/12 px-4">
            <div>
              <h1 className="font-semibold text-4xl md:text-5xl text-white">
                Dalal ak jàamm
              </h1>
              <p className="mt-5 text-lg leading-relaxed text-white max-w-xl">
                Mame Samba
              </p>
            </div>
          </div>
        </div>
      </section>




      {/* FEATURES */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4">
          <div className="text-center max-w-3xl mx-auto">
            <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">
              Ce que vous obtenez
            </h2>
            <p className="text-blueGray-500 mt-4">
              Un starter propre, réactif, et extensible pour présenter votre produit/service.
            </p>
          </div>
          {/* ... */}
        </div>
      </section>

      <Footer />
    </>
  );
}
